<template><div class="post-page"><template v-if="post"><header class="post-header"><router-link to="/blog">← 返回文章</router-link><div class="post-meta"><span>{{post.category||'随笔'}}</span><time>{{date(post.publishedAt)}}</time><span>{{post.viewCount}} 阅读</span></div><h1>{{post.title}}</h1><p v-if="post.summary">{{post.summary}}</p><div class="post-tags"><span v-for="tag in tags" :key="tag"># {{tag}}</span></div></header><div v-if="post.coverUrl" class="post-cover" :style="{backgroundImage:`url(${post.coverUrl})`}"/><article class="post-content"><MarkdownContent :content="post.markdownContent"/></article><footer class="post-end"><span>END</span><h3>感谢你读到这里。</h3><p>如果这篇文章对你有帮助，欢迎稍后再回来看看。</p><router-link to="/blog">继续浏览文章 →</router-link></footer></template><el-skeleton v-else :rows="10" animated/></div></template>
<script setup lang="ts">import{computed,onMounted,ref,watch}from'vue';import{useRoute}from'vue-router';import{getPublicBlogPost,type BlogPost}from'@/api/blog';import MarkdownContent from'@/components/MarkdownContent.vue';const route=useRoute(),post=ref<BlogPost>();const tags=computed(()=>post.value?.tags?.split(',').filter(Boolean)||[]);const date=(v:string|null)=>v?new Date(v).toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'}):'';async function load(){post.value=(await getPublicBlogPost(String(route.params.slug))).data;document.title=`${post.value.seoTitle||post.value.title} · 佳阳的数字花园`;document.querySelector('meta[name="description"]')?.setAttribute('content',post.value.seoDescription||post.value.summary||'');}onMounted(load);watch(()=>route.params.slug,load);</script>
<style scoped>.post-page{max-width:940px;padding:60px 24px 0;margin:auto}.post-header{max-width:800px;margin:auto;text-align:center}.post-header>a{display:inline-block;margin-bottom:30px;color:#64748b;font-size:13px;text-decoration:none}.post-meta{display:flex;gap:14px;justify-content:center;color:#94a3b8;font-size:12px}.post-meta span:first-child{color:#0f766e;font-weight:750}.post-header h1{margin:22px 0 18px;color:#14213a;font-family:Georgia,"Songti SC",serif;font-size:50px;line-height:1.28;letter-spacing:-.035em}.post-header>p{max-width:670px;margin:0 auto;color:#718096;font-size:17px;line-height:1.85}.post-tags{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:22px}.post-tags span{padding:6px 10px;color:#0f766e;background:#e8f5f2;border-radius:999px;font-size:11px}.post-cover{height:420px;margin:46px 0;background-position:center;background-size:cover;border-radius:26px;box-shadow:0 28px 70px rgb(15 23 42 / 15%)}.post-content{max-width:780px;padding:12px 0 30px;margin:auto}.post-end{max-width:780px;padding:48px 0;margin:40px auto 0;text-align:center;border-top:1px solid #dfe5e8}.post-end>span{color:#0f766e;font-size:10px;font-weight:800;letter-spacing:.25em}.post-end h3{margin:14px 0 8px;font-family:Georgia,"Songti SC",serif;font-size:24px}.post-end p{color:#8491a3}.post-end a{display:inline-block;margin-top:16px;color:#1d4ed8;font-weight:750;text-decoration:none}@media(max-width:640px){.post-page{padding:38px 18px 0}.post-header h1{font-size:34px}.post-header>p{font-size:15px}.post-cover{height:230px;margin:32px 0;border-radius:18px}}</style>
